import React from 'react';
import LeftSlidebarChecker from './leftSlidebarChecker';
import axiosInstance from "../configurations/instance";
import withNavigation from "../utils/withNavigation";

class CheckerProfile extends React.Component {
  constructor(props) {
    super(props);
    this.state = {
      isLoggedIn: true,
      userName: "",
    };
  }

  componentDidMount() {
    const token = localStorage.getItem("token");

    if (!token) {
      this.setState({ isLoggedIn: false });
      return;
    }

    // Запрос на получение имени и фамилии пользователя по ID из токена
    axiosInstance
      .get("/user/profile")
      .then((response) => {
        const { firstName, lastName } = response.data;
        this.setState({ userName: `${firstName} ${lastName}` });
      })
      .catch((error) => {
        console.error("Ошибка при загрузке профиля пользователя:", error);
      });
  }

  render() {
    if (!this.state.isLoggedIn) {
      this.props.navigate("/");
    }

    return (
      <div className="creating-page">
        <header className="main-header"></header>
        <div className="profile-page">
          <LeftSlidebarChecker />
          <div className="content">
            <h1>Профиль-страница</h1>
            <div className="profile-content">
              <h3>Добро пожаловать, {this.state.userName || "Пользователь"}!</h3>
            </div>
          </div>
        </div>
      </div>
    );
  }
}

export default withNavigation(CheckerProfile);
